-- Caso de cancelación confirmado por el propietario; sólo contenido editorial.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('cancelar-convenio-sin-pagos-500',$texto$Cancelar un convenio sin pagos: volver a adeudos de $300 y $200$texto$,'Cobranza',$texto$Retirar un acuerdo de $400.00 y reactivar sus originales de $500.00 sin cambiar caja o bancos.$texto$,$texto$Dos hijos inscritos del mismo plantel y tutor financiero, conceptos y cuotas nuevos de prueba sin ajustes ni pagos. Usuario administrativo persistido autorizado para conceptos, cuotas, adeudos, convenios y consulta de cuentas. Tutor con acceso financiero. No usar el convenio anterior de $800.00 liquidado; no reportar transferencias ni registrar pagos en este caso. Reutilizar registros preparados sin duplicarlos.$texto$,$texto$Originales300/200 total500 → acuerdo400/condonación100 → nuevos240/160. Al cancelar sin pagos, se cancelan los nuevos, regresan originales300/200 al portal y banco conservaB. En esta prueba se cancela un convenio, no se perdona la deuda.$texto$,1,DATE '2026-10-08','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='cancelar-convenio-sin-pagos-500';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('cancelar-convenio-sin-pagos-500',1,$texto$Preparar conceptos de esta prueba$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Conceptos de cobro; busca CONV-CANCEL-TEST → Aplicar filtros. 2. Si no existe, pulsa Nuevo registro y captura institución del ejemplo, código CONV-CANCEL-TEST, nombre Prueba de cancelación de convenio, categoría Otro y Activo Sí; sin becas, descuentos ni recargos. Pulsa Crear concepto. 3. Busca CONV-ACUERDO-TEST y reutiliza el concepto Convenio de pago de prueba, activo y de la misma institución. Si falta, créalo con categoría Otro y sin ajustes. 4. Identifica a los dos hijos ya inscritos, del mismo tutor responsable financiero y plantel. No reutilices el convenio de $800.00 que ya liquidaste.$texto$,$texto$Dos conceptos separados: adeudos originales y acuerdo nuevo.$texto$,$texto$Preparación sin operaciones financieras.$texto$,$texto$Si ya preparaste los registros, verificar y reutilizar; no duplicar conceptos ni expedientes.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('cancelar-convenio-sin-pagos-500',2,$texto$Crear cuotas únicas de $300 y $200$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro. 2. Selecciona institución, plantel, inscripción del primer hijo y CONV-CANCEL-TEST; Una sola vez, importe 300.00, fecha límite 20/10/2026, Estado Activa y generación automática. En Configuración adicional verifica vigencia dentro de inscripción/ciclo e inicio no posterior al corte 08/10/2026. 3. Pulsa Crear cuota → revisa Confirmar nueva cuota → Confirmar y crear cuota; Cancelar conserva la captura. 4. Regresa a Cuotas por alumno → Nuevo registro y repite con la inscripción del segundo hijo, mismo concepto y fechas, importe 200.00; confirma su cuota. Adapta fechas al ciclo y día institucional si reproduces otro día.$texto$,$texto$Primero $300.00 y segundo $200.00; total $500.00.$texto$,$texto$Dos cuotas independientes guardadas.$texto$,$texto$No repetir cuotas que ya generaron sus adeudos. El calendario del ejemplo debe ser válido para ambas inscripciones.$texto$,$texto$/admin/catalogos/cuotas-alumno$texto$),
('cancelar-convenio-sin-pagos-500',3,$texto$Generar sólo los dos originales$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos; selecciona institución, plantel y corte válido 08/10/2026. 2. Pulsa Visualizar cuotas por aplicar → Desmarcar todos; selecciona únicamente CONV-CANCEL-TEST por $300.00 y $200.00. Verifica dos registros, sin becas, total $500.00. 3. Pulsa Confirmar y generar adeudos seleccionados; revisa el modal y pulsa Confirmar y generar adeudos. Cancelar conserva la selección; el enlace ← Volver a adeudos de alumnos sólo navega sin emitir. 4. En el listado de Adeudos busca cada matrícula → Aplicar filtros → Ver → Resumen; anota números de cargo, abonos $0.00 y saldos $300.00/$200.00.$texto$,$texto$Dos cargos de prueba originales, no los de otro convenio.$texto$,$texto$Deuda inicial $500.00 emitida.$texto$,$texto$No generar ni seleccionar otros cargos. Una vista previa de sesión anterior puede requerir volver a visualizar.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-convenio-sin-pagos-500',4,$texto$Anotar saldo bancario B$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. 2. Busca la cuenta bancaria de prueba y pulsa Aplicar filtros. 3. Anota Saldo actual como B, por ejemplo $2,000.00; utiliza el saldo real que muestra tu cuenta. 4. No edites saldo inicial ni registres entradas o salidas: crear y cancelar este convenio no mueve dinero.$texto$,$texto$Referencia B antes del acuerdo.$texto$,$texto$Saldo para comparar al final.$texto$,$texto$Si existen movimientos concurrentes, distinguirlos de esta prueba.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('cancelar-convenio-sin-pagos-500',5,$texto$Crear otro convenio de $400 sin pagarlo$texto$,$texto$Administración$texto$,$texto$Convenios de pago$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago → Nuevo convenio. Selecciona institución, tutor y Concepto de cobro del convenio CONV-ACUERDO-TEST. 2. Busca CONV-CANCEL-TEST entre cargos pendientes del tutor → Buscar → Agregar únicamente los originales de $300.00 y $200.00; revisa Cargos agregados al convenio y saldo $500.00. 3. Captura acuerdo 08/10/2026, nueva fecha límite 20/10/2026, descripción Convenio de prueba para cancelar sin pagos, Nuevo monto total 400.00 y motivo Prueba controlada de cancelación de convenio sin pagos. Adapta fechas cuando corresponda. 4. Pulsa Confirmar convenio; revisa original $500.00, acuerdo $400.00 y condonado $100.00; pulsa Confirmar y crear convenio y anota el folio. No registres ningún pago ni transferencia.$texto$,$texto$Original500 → acuerdo400/condonación100.$texto$,$texto$Convenio creado sin ingreso.$texto$,$texto$Usar otro convenio: no cancelar el acuerdo anterior de $800.00 que ya tiene pagos.$texto$,$texto$/admin/convenios-pago$texto$),
('cancelar-convenio-sin-pagos-500',6,$texto$Verificar sustitución antes de cancelar$texto$,$texto$Administración y tutor$texto$,$texto$Convenios, adeudos y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca nuevo folio → aplica filtros → Ver → Adeudos. Anota cargos nuevos: $240.00 al primer hijo y $160.00 al segundo; sin abonos. 2. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver. Originales300/200 deben estar Convenidos y nuevos240/160 pendientes. 3. Abre una ventana privada separada de administración, entra a /familias e inicia sesión con el tutor; selecciona cada hijo → Tus pagos e identifica los cargos nuevos del convenio. 4. Sólo consulta: no pulses Enviar transferencia a revisión ni registres un pago en administración. Regresa a la ventana administrativa para cancelar.$texto$,$texto$Nuevos $240.00/$160.00 exigibles; originales sustituidos.$texto$,$texto$Origen y cargos del convenio identificados sin pagos.$texto$,$texto$Otros adeudos del alumno pueden existir: identifica por concepto/número, no sólo por total general del portal.$texto$,NULL),
('cancelar-convenio-sin-pagos-500',7,$texto$Cancelar con motivo y confirmar el modal$texto$,$texto$Administración$texto$,$texto$Convenios de pago → Gestión$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca el folio de esta prueba → aplica filtros → Ver → Gestión → Cancelar convenio. 2. Captura Motivo obligatorio Prueba controlada: se cancela el convenio sin pagos y se restauran los adeudos originales. Pulsa Cancelar y reactivar adeudos. 3. En Confirmar cancelación del convenio revisa folio, tutor, originales300/200 a reactivar, nuevos240/160 a cancelar, total original $500.00, acuerdo $400.00, condonación $100.00 y ningún efecto en caja/bancos. Pulsa Cancelar para comprobar que cierra sin ejecutar y conserva el motivo. 4. Pulsa nuevamente Cancelar y reactivar adeudos, revisa el mismo resumen y pulsa Confirmar cancelación del convenio. Espera el mensaje y estado Cancelado con el motivo conservado.$texto$,$texto$Se retira el acuerdo, no la deuda original.$texto$,$texto$Convenio y cargos nuevos cancelados; originales reactivados.$texto$,$texto$Cancelar dentro del modal sólo cierra. El servidor bloquea la cancelación si hay pagos aplicados; no eludir esa restricción.$texto$,$texto$/admin/convenios-pago$texto$),
('cancelar-convenio-sin-pagos-500',8,$texto$Comprobar restauración y regreso al portal familiar$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos, convenio, cuentas y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca cada matrícula → Aplicar filtros → Ver → Resumen de los originales anotados: pendientes $300.00 y $200.00, sin abonos. 2. En el mismo listado elige Estado Cancelado → Aplicar filtros y consulta los cargos nuevos240/160: historial conservado y sin saldo exigible. No deben cobrarse además de los originales. 3. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca folio → aplica filtros → Ver → Gestión. Confirma Convenio cancelado y motivo. 4. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca cuenta → Aplicar filtros y compara Saldo actual con B: no debe haber movimiento por el acuerdo ni su cancelación. 5. En la ventana familiar recarga Tus pagos de cada hijo; vuelve a identificar los originales $300.00/$200.00 como pendientes, sin nuevos240/160. No hay comprobante de pago de este caso porque nunca se pagó.$texto$,$texto$Deuda restaurada $500.00; bancoB; originales visibles otra vez para el tutor.$texto$,$texto$Caso completo confirmado por el propietario el 08/10/2026, incluida reaparición familiar300/200.$texto$,$texto$Cancelar el convenio no condona la deuda ni cancela los originales. No pagar ni cancelar esos cargos como parte de esta prueba.$texto$,NULL)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
